package Array;

public class MultiArray {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int arr[][]= {{10,11},{12,13},{14,15},{15,16}};
		for(int i=0;i<4;i++) {
			for(int j=0;j<2;j++) {
				System.out.println(arr[i][j]+"");
			}
			System.out.println();
		}
	
		}

}
